import{_ as a,o as t,c as d,ag as o}from"./chunks/framework.Dh3ZG9qC.js";const _=JSON.parse('{"title":"按键映射","description":"","frontmatter":{},"headers":[],"relativePath":"guide/keymap.md","filePath":"guide/keymap.md","lastUpdated":null}'),r={name:"guide/keymap.md"};function i(l,e,c,n,h,p){return t(),d("div",null,[...e[0]||(e[0]=[o('<h1 id="按键映射" tabindex="-1">按键映射 <a class="header-anchor" href="#按键映射" aria-label="Permalink to &quot;按键映射&quot;">​</a></h1><p>安装并启用 <code>gamer-keymap</code> 后，可以将键盘事件映射为设备上的触控、滑动或 Android 按键。</p><h2 id="配置一个方案" tabindex="-1">配置一个方案 <a class="header-anchor" href="#配置一个方案" aria-label="Permalink to &quot;配置一个方案&quot;">​</a></h2><ol><li>选择当前配置，在工作台打开「映射」。</li><li>新建方案，选择物理按键，例如 <code>Space</code> 或 <code>KeyE</code>。</li><li>选择动作类型并填写相对坐标或 Android keycode。</li><li>保存方案，在操控区域选择它并启用对应游戏输入模式。</li><li>在投屏区域获得键盘控制后测试，查看状态条中的控制状态。</li></ol><p>编辑文本时切回文本输入方式，避免把输入按键当成游戏操作。</p><h2 id="动作类型" tabindex="-1">动作类型 <a class="header-anchor" href="#动作类型" aria-label="Permalink to &quot;动作类型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>动作</th><th>行为</th></tr></thead><tbody><tr><td>按住 / <code>hold</code></td><td>键盘按下时触控 down，释放时触控 up；快速按一下形成点击</td></tr><tr><td>滑动 / <code>swipe</code></td><td>从起点滑到终点，使用指定持续时间</td></tr><tr><td>Android 按键 / <code>raw_key</code></td><td>发送 Android 按键事件，例如返回键</td></tr></tbody></table><p>屏幕坐标使用 0～1 的相对值。<code>raw_key</code> 发送 Android 按键，与按住屏幕坐标不同。</p><p>方案切换、失焦、页面隐藏或连接断开时，映射层会释放按住状态。未映射的按键按现有输入转发规则处理。</p><h2 id="原文编辑" tabindex="-1">原文编辑 <a class="header-anchor" href="#原文编辑" aria-label="Permalink to &quot;原文编辑&quot;">​</a></h2><p>可切换到 YAML 原文，保存前由服务端校验。同一方案内物理按键不能重复，未知动作与无效参数会拒绝保存。文件格式见<a href="./../reference/KEYMAP_SCHEMA.html">按键映射参考</a>。</p>',11)])])}const m=a(r,[["render",i]]);export{_ as __pageData,m as default};
